def stages(soc,standard):
 """Return nonzero costs only for explicitly modelled selected kernels."""
 out={}
 def add(node,lo,hi,basis,resource='aggregate'):
  out[node]={'known_model_Mcycles_per_s':[lo,hi],'basis':basis,'resource':resource}
 if standard=='T':
  if soc in ('C5','C61'):add('FIR',64*FS,64*FS,'Optimistic one real MAC/cycle, 32 taps for both I/Q; loads and control omitted')
  if soc=='S3':add('FIR',36*FS+3*16,48*FS+5*16,'Attachment fractional FIR plus raw-IQ unpack cycle profile')
  if soc=='S31':add('FIR',16*FS,32*FS,'Attachment SIMD FIR32 profile','PIE_core1')
  if soc in ('C5','C61'):add('FFT',10*(8192*13/2)/P,10*(8192*13/2)/P,'Selected scalar 10-cycle butterfly profile; not universal FFT floor')
  if soc=='S3':add('FFT',15623*10.4/P,15623*10.4/P,'Official 1024-point sc16 benchmark scaled by NlogN; estimate, excludes reorder')
  if soc=='S31':add('FFT',2*21*10.4*320/P,2*21*10.4*320/P,'Attachment two-real-FFT Q15 extrapolation; excludes reverse/merge','PIE_core1')
  if soc in ('S3','S31'):
   add('equalize_demap',8*DATA,16*DATA,'Attachment cycles/carrier assumption')
   add('time_deinterleave',16*DATA,32*DATA,'Attachment coalesced-address cycle profile; memory traffic separately checked')
  add('Viterbi',64*STEPS*3,64*STEPS*6,'Scalar-equivalent ACS work; use heterogeneous lane capacity test, not aggregate CPU sum','ACS_lanes')
 else:
  if soc in ('C5','C61'):add('FIR',32*28.86,32*28.86,'Optimistic one real MAC/cycle, 16 taps I/Q; loads/control omitted')
  if soc=='S3':add('FIR',26*28.86+3*40,36*28.86+5*40,'Attachment fractional FIR16 plus raw unpack profile')
  if soc=='S31':add('FIR',5*28.86,10*28.86,'Existing N3-S FIR16 design range','PIE_core1')
  tc=tc16(soc)
  add('TC8PSK',tc['required_main_M_ACS_per_s']*3,tc['required_main_M_ACS_per_s']*6,'ITU-R BO.1408-1 K=7, B0 convolutional and B1 uncoded; ordinary 16bit ACS main-signal-only lower bound','TC_ACS_lanes')
  fs=frame_store_cpu()
  add('frame_deinterleave',*fs['processing_Mcycles_per_s'],'Scalar scatter/gather plus sync-byte insertion; descrambler remains with FPGA RS input')
 rate=(T_TS if standard=='T' else S_TS)/188
 rs=rs_model()
 add('RS',rs['selected_kernel_arithmetic_floor_cycles']*rate,rs['total_cycles_budget']*rate,'New scalar table-based RS profile, packet-independent workers allowed')
 return out
